mapper.select:
SELECT s.id, s.project_id, s.name, s.description, s.scope, s.enabled, s.default_apply,
       s.sort_order, s.archived, s.source_project_id, s.source_standard_id,
       s.source_version_id, s.source_version_no, s.created_at, s.updated_at
FROM code_standard s
JOIN project p ON p.id = s.project_id
WHERE s.id = #{id}
  AND (
      p.owner_id = #{ownerId}
      OR EXISTS (
          SELECT 1 FROM project_member pm
          WHERE pm.project_id = p.id AND pm.user_id = #{ownerId}
      )
  )
  AND p.deleted = 0
